//! Wire-level interop regression tests against the browser build.
//!
//! The fixtures below were generated by the original JavaScript
//! implementation (`lib/optical-transfer.ts` + the RaptorQ WASM) from fixed
//! inputs:
//!
//! - data: 1000 bytes of `i % 251` (deterministic)
//! - filename "sample.bin", mime "application/octet-stream", no compression
//! - transport payload size 256, repair percent 30
//!
//! The Rust crate must reproduce those bytes exactly, and must decode the
//! browser stream. Regenerate with the browser's `wire-fixture.mts` script
//! and `examples/wire_fixture.rs` if the protocol ever evolves.

use qrferry::{
    build_optical_container, create_optical_transfer, parse_frame, CompressionMode, RaptorQDecoder,
};

const JS_CONTAINER_HEX: &str = "";

const JS_FRAMES_HEX: &str = "";

fn hex_to_bytes(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect()
}

fn browser_container() -> Vec<u8> {
    hex_to_bytes(JS_CONTAINER_HEX)
}

fn browser_frames() -> Vec<u8> {
    hex_to_bytes(JS_FRAMES_HEX)
}

fn rust_frames() -> Vec<u8> {
    let original: Vec<u8> = (0..1000).map(|i| (i % 251) as u8).collect();
    let prepared = build_optical_container(
        &original,
        &original,
        "sample.bin",
        "application/octet-stream",
        CompressionMode::None,
    )
    .unwrap();
    let transfer = create_optical_transfer(&prepared, 256, 30).unwrap();
    transfer.packets.concat()
}

#[test]
fn rust_output_is_byte_identical_to_browser() {
    let original: Vec<u8> = (0..1000).map(|i| (i % 251) as u8).collect();
    let prepared = build_optical_container(
        &original,
        &original,
        "sample.bin",
        "application/octet-stream",
        CompressionMode::None,
    )
    .unwrap();
    assert_eq!(prepared.container, browser_container());

    let frames = rust_frames();
    assert_eq!(frames.len(), browser_frames().len());
    assert_eq!(frames, browser_frames());
}

#[test]
fn rust_decoder_recovers_browser_stream() {
    let container = browser_container();
    let frames = browser_frames();
    let mut decoder = RaptorQDecoder::new(container.len() as u32, 256).unwrap();
    let mut recovered = None;
    for frame_bytes in frames.chunks(279) {
        let frame = parse_frame(frame_bytes).unwrap();
        assert_eq!(frame.symbol_size, 256);
        if let Some(full) = decoder.push(&frame.payload).unwrap() {
            recovered = Some(full);
            break;
        }
    }
    assert_eq!(recovered.expect("browser stream did not decode"), container);
}
